-- E0.9 lab, client half: reports what THIS client renders for the vehicle-kit parts.
-- Generated by scripts/vehicle-kit/build-pack.ps1 from scripts/vehicle-kit/lua/e09_client.lua.
-- It changes nothing: it lists the vehicle's named slots and each part's projection
-- state, which is what decides between a slot binding and a root binding.
local function report(vehicle, props)
    local bones, err = Open77.props.bones('vehicle', vehicle)
    if not bones then return print(('[vkit] bones of vehicle %s: %s'):format(tostring(vehicle), tostring(err))) end
    local wheels = {}
    for _, name in ipairs(bones) do if name:find('wheel', 1, true) then wheels[#wheels + 1] = name end end
    print(('[vkit] vehicle %s: %d named slots; wheel slots: %s'):format(tostring(vehicle), #bones,
        #wheels > 0 and table.concat(wheels, ' ') or 'NONE (not streamed, or bind the rims to the root)'))
    print('[vkit] all slots: ' .. table.concat(bones, ' '))
    -- props.projected is newer than the published 2.50.0+op77.156 catalogue: optional.
    if type(Open77.props.projected) ~= 'function' then return end
    for _, id in ipairs(props or {}) do
        local snap = Open77.props.projected(id)
        print(('[vkit] prop %s rendered=%s attachmentStatus=%s'):format(tostring(id),
            snap and tostring(snap.rendered) or 'not projected', snap and tostring(snap.attachmentStatus) or '-'))
    end
end

RegisterNetEvent('@@RESOURCE@@:inspect', function(vehicle, props)
    CreateThread(function()
        Wait(1500)   -- give the projection time to bind its slot before reading it
        report(vehicle, props)
    end)
end)

-- /vkit.bones [vehicleId]   without an id: the car this player sits in
if type(RegisterCommand) == 'function' then
    pcall(RegisterCommand, 'vkit.bones', function(_, args)
        local vehicle = tonumber(args and args[1])
        if not vehicle then
            local seat = Open77.vehicles and Open77.vehicles.getPlayerSeat and Open77.vehicles.getPlayerSeat()
            vehicle = seat and tonumber(seat.vehicleId)
        end
        if not vehicle then return print('[vkit] usage: vkit.bones <vehicleId>, or sit in the car') end
        report(vehicle, {})
    end, false)
end
